mapper.select:
SELECT * FROM tb_viam_credential_enrollment
WHERE vin = #{vin} AND hsm_uid = #{hsmUid}
  AND certificate_profile = #{certificateProfile}
  AND (public_key_sha256 = #{publicKeySha256} OR (#{publicKeySha256} IS NULL AND public_key_sha256 IS NULL))
  AND row_valid = 1
LIMIT 1

SELECT * FROM tb_viam_credential_enrollment
WHERE vin = #{vin} AND hsm_uid = #{hsmUid}
  AND certificate_profile = #{certificateProfile}
  AND public_key_sha256 IS NOT NULL
  AND public_key_sha256 != #{publicKeySha256}
  AND cert_status IN ('REQUESTED','ISSUING','PENDING_RECONCILE','ISSUED_NOT_CONFIRMED','ACTIVE')
  AND row_valid = 1
LIMIT 1
